    {"name": "write", "arguments": {"path": "src/lib.rs", "overwrite": True, "content": "use std::fmt::Display;\nuse std::marker::PhantomData;\nuse std::ops::Rem;\n\n/// A Matcher is a single rule of fizzbuzz.\npub struct Matcher<T>(Box<dyn Fn(T) -> bool>, String, PhantomData<T>);\n\nimpl<T> Matcher<T> {\n    pub fn new<F, S>(matcher: F, subs: S) -> Matcher<T>\n    where F: Fn(T) -> bool + 'static, S: Into<String> {\n        Matcher(Box::new(matcher), subs.into(), PhantomData)\n    }\n}\n\n/// An ordered set of matchers applied to each iterator element.\npub struct Fizzy<T>(Vec<Matcher<T>>);\n\nimpl<T> Fizzy<T> {\n    pub fn new() -> Self { Self(Vec::new()) }\n\n    #[must_use]\n    pub fn add_matcher(mut self, matcher: Matcher<T>) -> Self {\n        self.0.push(matcher);\n        self\n    }\n\n    pub fn apply<I>(self, iter: I) -> impl Iterator<Item = String>\n    where I: IntoIterator<Item = T>, T: Copy + Display {\n        iter.into_iter().map(move |item| {\n            let result: String = self.0.iter()\n                .filter(|matcher| (matcher.0)(item))\n                .map(|matcher| matcher.1.as_str())\n                .collect();\n            if result.is_empty() { item.to_string() } else { result }\n        })\n    }\n}\n\nimpl<T> Default for Fizzy<T> { fn default() -> Self { Self::new() } }\n\npub fn fizz_buzz<T>() -> Fizzy<T>\nwhere T: Copy + Display + PartialEq + Rem<Output = T> + From<u8> + 'static {\n    Fizzy::new()\n        .add_matcher(Matcher::new(|n| n % T::from(3) == T::from(0), \"fizz\"))\n        .add_matcher(Matcher::new(|n| n % T::from(5) == T::from(0), \"buzz\"))\n}\n\n#[cfg(test)]\nmod tests {\n    use super::{fizz_buzz, Fizzy, Matcher};\n\n    #[test]\n    fn custom_matchers_combine_in_order_and_fall_back_to_display() {\n        let fizz = Fizzy::new()\n            .add_matcher(Matcher::new(|n: u32| n % 2 == 0, \"even\"))\n            .add_matcher(Matcher::new(|n: u32| n % 3 == 0, \"tri\"));\n        assert_eq!(fizz.apply([1, 2, 3, 6]).collect::<Vec<_>>(), [\"1\", \"even\", \"tri\", \"eventri\"]);\n    }\n\n    #[test]\n    fn standard_rules() {\n        assert_eq!(fizz_buzz::<u32>().apply(1..=15).collect::<Vec<_>>(), [\n            \"1\", \"2\", \"fizz\", \"4\", \"buzz\", \"fizz\", \"7\", \"8\",\n            \"fizz\", \"buzz\", \"11\", \"fizz\", \"13\", \"14\", \"fizzbuzz\"\n        ]);\n    }\n}\n"}},
